-- =============================================================================
-- 449 — LE CAHIER D'EXERCICES DE TLE (partie 14)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 449 --niveau Tle --matieres svt --suffixe 14 > supabase/contenu/449_exercices_tle_14.sql
--
-- 66 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   svt.k199                33 exercices · 11 chapitres
--   svt.k200                33 exercices · 11 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('ac28148f-026b-5300-88ee-0495af4adf1d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le filon dans la falaise","competence":"observer-schema","situation":"Sur une falaise non déformée, Nora observe quatre couches sédimentaires empilées et un filon de basalte, une roche volcanique qui s’est injectée dans les couches.","documents":[{"id":"coupe","type":"schema","titre":"La falaise de Nora","largeur":340,"hauteur":236,"elements":[{"forme":"rect","x":40,"y":30,"l":200,"h":40,"teinte":"brun","motif":"clair","id":"z1","zone":true},{"forme":"rect","x":40,"y":70,"l":200,"h":40,"teinte":"brun","motif":"points","id":"z2","zone":true},{"forme":"rect","x":40,"y":110,"l":200,"h":40,"teinte":"brun","motif":"hachures","id":"z3","zone":true},{"forme":"rect","x":40,"y":150,"l":200,"h":40,"teinte":"brun","motif":"clair","id":"z4","zone":true},{"forme":"rect","x":132,"y":70,"l":16,"h":120,"teinte":"encre","motif":"plein","id":"z5","zone":true},{"forme":"texte","x":252,"y":54,"texte":"Couche D","taille":"petit","ancre":"debut"},{"forme":"texte","x":252,"y":94,"texte":"Couche C","taille":"petit","ancre":"debut"},{"forme":"texte","x":252,"y":134,"texte":"Couche B","taille":"petit","ancre":"debut"},{"forme":"texte","x":252,"y":174,"texte":"Couche A","taille":"petit","ancre":"debut"},{"forme":"texte","x":140,"y":210,"texte":"Filon de basalte","taille":"petit","ancre":"milieu"}]}],"questions":[{"enonce":"Touche la couche la plus ancienne.","aide":"Dans une série non déformée, on lit le temps du bas vers le haut.","type":"zone","document":"coupe","multiple":false},{"enonce":"Le filon traverse les couches A, B et C, mais pas la couche D. Que peut-on en conclure ?","aide":"Ce qui recoupe est plus récent que ce qui est recoupé ; D n’est pas recoupée.","type":"choix","options":[{"id":"a","texte":"Il est plus récent que C et plus ancien que D"},{"id":"b","texte":"Il a exactement le même âge que la couche B"},{"id":"c","texte":"Il est plus récent que la couche D"},{"id":"d","texte":"Il est plus ancien que la couche A"}],"multiple":false},{"enonce":"Range ces événements du plus ancien au plus récent.","aide":"Les couches d’abord, dans l’ordre du bas vers le haut ; le filon s’insère quand C existe déjà.","type":"ordre","items":[{"id":"a","texte":"Dépôt de la couche C"},{"id":"b","texte":"Dépôt de la couche A"},{"id":"c","texte":"Arrivée du filon de basalte"},{"id":"d","texte":"Dépôt de la couche B"},{"id":"e","texte":"Dépôt de la couche D"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"C’est la couche **A**, tout en bas : d’après le principe de superposition, elle s’est déposée la première."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le filon recoupe C : il est **postérieur à C**. La couche D, non traversée, s’est déposée après lui."},{"cle":{"type":"ordre","ids":["b","d","a","c","e"]},"explication":"A, B, C, puis le **filon**, qui recoupe C, et enfin D qui le recouvre."}]$ex$::jsonb),
  ('ac28148f-026b-5300-88ee-0495af4adf1d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La carrière à l’envers","competence":"analyser-document","situation":"Dans une carrière, des bancs de grès sont très inclinés. Un banc déposé normalement a ses grains les plus gros en bas ; ses fentes de dessiccation, creusées depuis la surface du sol, sont larges en haut et finissent en pointe vers le bas.","documents":[{"id":"bancs","type":"tableau","titre":"Relevés sur trois bancs","colonnes":["Banc","Grains en bas","Grains en haut","Fentes larges vers…"],"lignes":[["Banc 1 (le plus bas)","fins","grossiers","le bas"],["Banc 2 (au milieu)","fins","grossiers","le bas"],["Banc 3 (le plus haut)","fins","grossiers","le bas"]],"enteteLignes":true,"source":"Relevés imaginés pour l’exercice"}],"questions":[{"enonce":"Que disent le granoclassement et les fentes de dessiccation de cette série ?","aide":"Compare avec un banc déposé normalement : gros grains où ? fentes larges où ?","type":"choix","options":[{"id":"a","texte":"Elle est normale, mais les bancs sont mal classés"},{"id":"b","texte":"Elle est normale : le plus ancien est en bas"},{"id":"c","texte":"Elle est renversée : le haut actuel était le bas à l’origine"},{"id":"d","texte":"On ne peut rien savoir sans dater les roches"}],"multiple":false},{"enonce":"Touche la case du banc 3 qui indique où ses fentes de dessiccation sont larges.","aide":"Lis la dernière colonne, troisième ligne.","type":"zone","document":"bancs","multiple":false},{"enonce":"Range les bancs du plus ancien au plus récent.","aide":"Comme la série est renversée, le principe de superposition se lit à l’envers.","type":"ordre","items":[{"id":"a","texte":"Banc 3 (le plus haut)"},{"id":"b","texte":"Banc 1 (le plus bas)"},{"id":"c","texte":"Banc 2 (au milieu)"}]},{"enonce":"Complète la conclusion.","aide":"Le dernier déposé est au sommet de la série d’origine.","type":"trous","segments":["Comme la série est ",0,", c’est le banc le plus ",1," de la carrière qui s’est déposé en dernier."],"banque":["normale","renversée","bas","haut"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"Les gros grains sont **en haut** et les fentes sont larges **vers le bas** : c’est l’inverse d’un dépôt normal. La série est **renversée**."},{"cle":{"type":"zone","ids":["r2c3"]},"explication":"Pour le banc 3, les fentes sont larges vers **le bas**, ce qui trahit le renversement."},{"cle":{"type":"ordre","ids":["a","c","b"]},"explication":"La série étant renversée, le banc le plus haut est le plus **ancien** : 3, puis 2, puis 1."},{"cle":{"type":"trous","trous":[["renversee"],["bas"]]},"affichage":"renversée · bas","explication":"Série **renversée** : le sommet d’origine est en bas, donc le banc le plus **bas** est le plus récent."}]$ex$::jsonb),
