   $ex${"titre":"Quelle horloge pour quel objet ?","competence":"analyser-document","situation":"Un laboratoire de datation reçoit trois échantillons. Pour chacun, il faut choisir le couple père-fils dont la demi-vie est du même ordre que l’âge cherché.","documents":[{"id":"echantillons","type":"tableau","titre":"Les échantillons","colonnes":["Échantillon","Âge supposé"],"lignes":[["Bois d’une pirogue","environ 3 000 ans"],["Coulée de basalte","quelques millions d’années"],["Zircon d’un granite","environ 4 milliards d’années"]],"enteteLignes":true},{"id":"couples","type":"tableau","titre":"Les horloges disponibles","colonnes":["Couple","Demi-vie"],"lignes":[["Carbone 14 → azote 14","5 730 ans"],["Potassium 40 → argon 40","1,3 milliard d’années"],["Uranium → plomb","4,5 milliards d’années"]],"enteteLignes":true,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Associe chaque échantillon au couple le mieux adapté.","aide":"Cherche la demi-vie du même ordre que l’âge.","type":"association","gauche":[{"id":"g0","texte":"Bois d’une pirogue"},{"id":"g1","texte":"Coulée de basalte"},{"id":"g2","texte":"Zircon d’un granite"}],"droite":[{"id":"d0","texte":"Potassium 40 → argon 40"},{"id":"d1","texte":"Uranium → plomb"},{"id":"d2","texte":"Carbone 14 → azote 14"}]},{"enonce":"Un bois contient 80 atomes de carbone 14 à la mort de l’arbre. Combien en restera-t-il après une demi-vie, soit 5 730 ans ?","aide":"À chaque demi-vie, il reste la moitié des atomes pères.","type":"nombre","unite":"atomes"},{"enonce":"Touche le couple dont la demi-vie est du même ordre que l’âge de la Terre.","aide":"La Terre a 4,57 milliards d’années.","type":"zone","document":"couples","multiple":false}]}$ex$::jsonb,
