   $ex${"titre":"L’épi qui garde ses grains","competence":"experimenter","situation":"Dans une simulation simplifiée, on récolte chaque année des céréales sauvages à la date de la moisson, puis on ressème seulement les grains récoltés. Au départ, 1 % des épis gardent leurs grains.","documents":[{"id":"protocole","type":"texte","genre":"article","titre":"Le protocole","auteur":"Texte écrit pour l’exercice","blocs":["Les épis « cassants » laissent tomber leurs grains au sol avant la moisson. Les épis « non cassants » les gardent jusqu’à la récolte.","Chaque année, le cultivateur ne ressème que les grains qu’il a récoltés."]},{"id":"courbe","type":"graphique","forme":"courbe","titre":"Épis qui gardent leurs grains","categories":["0","1","2","3","4","5"],"series":[{"nom":"Épis non cassants","valeurs":[1,5,18,55,85,96],"teinte":"vert"}],"axeY":{"titre":"Épis non cassants","unite":"en % des épis","min":0,"max":100,"pas":20},"axeX":{"titre":"Années de ressemis"},"valeurs":false,"source":"Simulation simplifiée"}],"questions":[{"enonce":"Touche l’année où les épis non cassants deviennent majoritaires.","aide":"Cherche la première année où la courbe dépasse 50 %.","type":"zone","document":"courbe","multiple":false},{"enonce":"Quel pourcentage d’épis non cassants lit-on à la 2e année ?","aide":"Lis la valeur de la courbe à la graduation 2.","type":"nombre","unite":"%"},{"enonce":"Pourquoi la part des épis non cassants augmente-t-elle d’année en année ?","aide":"Regarde ce qui arrive aux grains d’un épi cassant avant la moisson.","type":"choix","options":[{"id":"a","texte":"Le cultivateur choisit volontairement chaque année les épis qui gardent leurs grains"},{"id":"b","texte":"Les épis non cassants produisent beaucoup plus de grains que les épis cassants"},{"id":"c","texte":"Les grains des épis cassants tombent avant la moisson et ne sont donc pas ressemés"},{"id":"d","texte":"Les grains des épis cassants sont détruits à chaque fois par la moisson elle-même"}],"multiple":false},{"enonce":"Quelle est la conséquence pour la plante devenue majoritairement non cassante ?","aide":"Un épi qui garde ses grains peut-il les semer au sol tout seul ?","type":"choix","options":[{"id":"a","texte":"Elle devient plus résistante aux parasites qu’elle ne l’était dans l’état sauvage"},{"id":"b","texte":"Elle se dissémine encore plus loin qu’avant grâce à des épis plus solides et plus gros"},{"id":"c","texte":"Elle ne disperse plus ses grains seule et dépend des humains pour se reproduire"},{"id":"d","texte":"Elle cesse de produire des grains, ce qui oblige les humains à la ressemer chaque année"}],"multiple":false}]}$ex$::jsonb,
