   $ex${"titre":"La glace qui s’auto-entretient","competence":"raisonner","situation":"Sur une région de latitude élevée, chaque mètre carré reçoit 300 W/m² en été. Un refroidissement fait avancer la glace, et la nature de la surface change.","documents":[{"id":"boucle","type":"chaine","disposition":"cycle","noeuds":[{"id":"z1","texte":"Il fait plus froid"},{"id":"z2","texte":"La glace s’étend"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Moins d’énergie solaire absorbée"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z1"}]},{"id":"alb","type":"tableau","titre":"Albédo de quelques surfaces","colonnes":["Surface","Albédo"],"lignes":[["Océan libre","6 %"],["Forêt","15 %"],["Neige fraîche","80 %"]],"enteteLignes":true,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Que faut-il écrire à la place du « ? » dans la boucle ?","aide":"Regarde le tableau : la glace et la neige sont-elles sombres ou claires ?","type":"choix","options":[{"id":"a","texte":"Les océans libèrent davantage de CO₂ dans l’atmosphère"},{"id":"b","texte":"La surface renvoie davantage d’énergie (albédo plus fort)"},{"id":"c","texte":"L’atmosphère absorbe davantage d’infrarouge (effet de serre)"},{"id":"d","texte":"La surface renvoie moins d’énergie (albédo plus faible)"}],"multiple":false},{"enonce":"Quelle puissance par mètre carré l’océan libre absorbe-t-il ?","aide":"Il absorbe la part qu’il ne renvoie pas : 100 % − 6 %.","type":"nombre","unite":"W/m²"},{"enonce":"Quelle puissance par mètre carré la neige fraîche absorbe-t-elle ?","aide":"Elle absorbe 100 % − 80 % = 20 % de 300.","type":"nombre","unite":"W/m²"},{"enonce":"Touche la surface qui, en remplaçant l’océan libre, renforce le plus le refroidissement.","aide":"Cherche la surface qui renvoie le plus d’énergie.","type":"zone","document":"alb","multiple":false},{"enonce":"Quand la glace fond, que se passe-t-il dans cette boucle ?","aide":"La rétroaction de l’albédo amplifie dans les deux sens.","type":"choix","options":[{"id":"a","texte":"Elle ne concerne que la banquise, sans conséquence pour les continents"},{"id":"b","texte":"Elle s’inverse en rétroaction négative qui freine tout de suite le réchauffement"},{"id":"c","texte":"Elle s’arrête : l’albédo ne joue aucun rôle dans un réchauffement du climat"},{"id":"d","texte":"Elle agit dans l’autre sens : l’albédo baisse et le réchauffement est amplifié"}],"multiple":false}]}$ex$::jsonb,
