  ('cb4a20c7-1bcd-575a-b1d6-cbdaea881613'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’oxygène des coquilles","competence":"analyser-document","situation":"Des foraminifères, petits organismes marins, fabriquent leur coquille calcaire avec l’oxygène de l’eau où ils vivent. Une carotte de sédiments marins permet de suivre leur δ18O (proportion d’isotope lourd) sur 120 000 ans.","documents":[{"id":"principe","type":"texte","genre":"article","titre":"Le principe","auteur":"Texte écrit pour l’exercice","blocs":["L’isotope léger de l’oxygène s’évapore plus facilement que l’isotope lourd. En période glaciaire, il est piégé dans les glaces des continents : l’océan s’enrichit en isotope lourd.","Le δ18O des coquilles dépend aussi de la température de l’eau."]},{"id":"d18o","type":"graphique","forme":"courbe","titre":"δ18O des foraminifères","categories":["0","20","40","60","80","100","120"],"series":[{"nom":"δ18O","valeurs":[3.4,5,4.4,4.2,4.4,4,3.3],"teinte":"bleu"}],"axeY":{"titre":"δ18O","unite":"en ‰","min":3,"max":5.5,"pas":0.5},"axeX":{"titre":"Il y a … milliers d’années"},"valeurs":false,"source":"Données simplifiées"}],"questions":[{"enonce":"Touche le moment où l’océan est le plus enrichi en isotope lourd.","aide":"Cherche la valeur la plus élevée de la courbe.","type":"zone","document":"d18o","multiple":false},{"enonce":"Quel est l’écart de δ18O entre le maximum et le minimum de la courbe ?","aide":"Maximum : 5,0. Minimum : 3,3.","type":"nombre","unite":"‰"},{"enonce":"Que peut-on dire des glaces continentales il y a 20 000 ans ?","aide":"Quand le δ18O de l’océan est fort, où est passé l’isotope léger ?","type":"choix","options":[{"id":"a","texte":"Elles étaient beaucoup plus volumineuses qu’aujourd’hui"},{"id":"b","texte":"Elles étaient à peu près aussi étendues qu’aujourd’hui"},{"id":"c","texte":"Elles n’existaient pas encore sur les continents"},{"id":"d","texte":"Elles étaient moins étendues qu’aujourd’hui"}],"multiple":false},{"enonce":"Pourquoi le δ18O des coquilles ne donne-t-il pas à lui seul la température de l’eau ?","aide":"Relis le texte : deux causes font varier le δ18O.","type":"choix","options":[{"id":"a","texte":"Il dépend seulement de la profondeur à laquelle vivait chaque foraminifère"},{"id":"b","texte":"Il dépend seulement de la salinité de l’eau au moment de la mort de l’organisme"},{"id":"c","texte":"Il ne dépend d’aucun paramètre du milieu et reste constant au cours du temps"},{"id":"d","texte":"Il dépend à la fois de la température de l’eau et du volume des glaces"}],"multiple":false}]}$ex$::jsonb,
