   $ex${"titre":"Combien de gamètes différents ?","competence":"modeliser","situation":"Dans une espèce fictive, on calcule le nombre de gamètes différents que le seul brassage interchromosomique peut produire, selon le nombre de paires de chromosomes.","documents":[{"id":"paires","type":"tableau","titre":"Brassage interchromosomique","colonnes":["Paires de chromosomes","Gamètes différents possibles"],"lignes":[["1",2],["2",4],["3",8],["4","?"]],"enteteLignes":true,"source":"Chaque paire se répartit indépendamment des autres"}],"questions":[{"enonce":"Touche le nombre de gamètes différents possibles pour 3 paires.","aide":"Cherche la ligne « 3 ».","type":"zone","document":"paires","multiple":false},{"enonce":"Combien de gamètes différents avec 4 paires de chromosomes ?","aide":"À chaque paire, le nombre double.","type":"nombre","unite":"gamètes"},{"enonce":"Une espèce a 2n = 10 chromosomes. Combien de gamètes différents par brassage interchromosomique seul ?","aide":"2n = 10, donc 5 paires. Calcule 2 à la puissance 5.","type":"nombre","unite":"gamètes"},{"enonce":"Pourquoi ce nombre sous-estime-t-il la diversité réelle des gamètes ?","aide":"Il existe un second brassage dans la méiose, avant l’anaphase I.","type":"choix","options":[{"id":"a","texte":"Les crossing-over de la prophase I s’ajoutent au brassage interchromosomique"},{"id":"b","texte":"La fécondation ajoute une paire de chromosomes supplémentaire à chaque gamète"},{"id":"c","texte":"Les mutations de l’ADN s’ajoutent à chaque méiose et changent la forme des gamètes"},{"id":"d","texte":"Le nombre de chromosomes change à chaque méiose et augmente le nombre de paires"}],"multiple":false}]}$ex$::jsonb,
