  ('0e3dc8f8-ad81-592f-8039-c88b77388716'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Des mouches qui trichent","competence":"lire-tableau","situation":"Chez la drosophile, deux gènes sont étudiés : la couleur du corps (gris ou noir) et la forme des ailes (normales ou vestigiales). On croise une femelle hétérozygote pour les deux gènes avec un mâle noir aux ailes vestigiales, double récessif : c’est un croisement-test.","documents":[{"id":"morgan","type":"tableau","titre":"Descendants du croisement-test","colonnes":["Phénotype","Nombre de descendants"],"lignes":[["Gris, ailes normales",965],["Noir, ailes vestigiales",944],["Gris, ailes vestigiales",206],["Noir, ailes normales",185]],"enteteLignes":true,"source":"D’après les résultats historiques de Morgan"}],"questions":[{"enonce":"Touche le phénotype le moins fréquent.","aide":"Cherche le plus petit effectif.","type":"zone","document":"morgan","multiple":false},{"enonce":"Combien de descendants au total ?","aide":"Additionne les quatre effectifs.","type":"nombre","unite":"descendants"},{"enonce":"Quel pourcentage de descendants sont recombinés, arrondi à l’unité ?","aide":"Les recombinés sont les deux phénotypes minoritaires. Additionne-les, divise par le total.","type":"nombre","unite":"%"},{"enonce":"Que conclure sur la position des deux gènes ?","aide":"Quatre phénotypes en proportions égales (25 % chacun) indiqueraient des gènes indépendants.","type":"choix","options":[{"id":"a","texte":"Ils sont liés : proches sur un même chromosome, avec peu de recombinés"},{"id":"b","texte":"Ils sont indépendants : les quatre phénotypes seraient en proportions égales"},{"id":"c","texte":"Ils sont éloignés sur le même chromosome, avec autant de recombinés que de parentaux"},{"id":"d","texte":"Ils sont situés sur des chromosomes différents, donc sans aucun recombiné possible"}],"multiple":false},{"enonce":"Quel événement de la méiose explique les phénotypes recombinés ?","aide":"Les recombinés résultent d’un échange entre chromosomes homologues.","type":"choix","options":[{"id":"a","texte":"Une non-disjonction qui touche 17 % des paires de chromosomes homologues"},{"id":"b","texte":"Une mutation qui se produit dans 17 % des gamètes lors de la réplication"},{"id":"c","texte":"Un brassage interchromosomique, à l’anaphase de la division II"},{"id":"d","texte":"Un crossing-over entre les deux gènes, en prophase de la division I"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c0"]},"explication":"Le phénotype « noir, ailes normales » est le moins fréquent, avec **185** descendants."},{"cle":{"type":"nombre","valeur":2300,"tolerance":0},"affichage":"2300 descendants","explication":"965 + 944 + 206 + 185 = **2 300**."},{"cle":{"type":"nombre","valeur":17,"tolerance":0},"affichage":"17 %","explication":"(206 + 185) ÷ 2 300 = 391 ÷ 2 300 ≈ **17 %**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Deux phénotypes **parentaux majoritaires** et deux **recombinés minoritaires** : les gènes sont **liés**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Un **crossing-over** en prophase I échange des portions entre homologues : il sépare des allèles normalement liés."}]$ex$::jsonb),
  ('0e3dc8f8-ad81-592f-8039-c88b77388716'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Quand la méiose dérape","competence":"raisonner","situation":"Lors de la méiose d’une cellule humaine (2n = 46), la paire de chromosomes 21 se répartit anormalement : c’est une non-disjonction. Deux tableaux comparent les quatre gamètes selon qu’elle a lieu en division I ou en division II.","documents":[{"id":"div1","type":"tableau","titre":"Non-disjonction en division I","colonnes":["Gamète","Chromosomes","Exemplaires du 21"],"lignes":[["Gamète 1",24,2],["Gamète 2",24,2],["Gamète 3",22,0],["Gamète 4",22,0]],"enteteLignes":true,"source":"Schéma simplifié"},{"id":"div2","type":"tableau","titre":"Non-disjonction en division II","colonnes":["Gamète","Chromosomes","Exemplaires du 21"],"lignes":[["Gamète 1",24,2],["Gamète 2",22,0],["Gamète 3",23,1],["Gamète 4",23,1]],"enteteLignes":true,"source":"Schéma simplifié"}],"questions":[{"enonce":"En division I, touche les deux gamètes qui donneraient une trisomie 21 après fécondation par un gamète normal.","aide":"Il faut trois exemplaires du chromosome 21 dans le zygote : donc deux dans le gamète anormal.","type":"zone","document":"div1","multiple":true},{"enonce":"Combien de chromosomes le zygote compte-t-il si le gamète 1 est fécondé par un gamète normal à 23 chromosomes ?","aide":"Additionne 24 et 23.","type":"nombre","unite":"chromosomes"},{"enonce":"En division II, combien de gamètes sur quatre sont normaux (23 chromosomes, un seul 21) ?","aide":"Compte les gamètes à 23 chromosomes dans le second tableau.","type":"nombre","unite":"gamètes"},{"enonce":"Pourquoi aucun gamète n’est-il normal quand l’accident a lieu en division I ?","aide":"La division I sépare les chromosomes homologues : que devient la paire qui ne se sépare pas ?","type":"choix","options":[{"id":"a","texte":"Les chromatides sœurs se séparent normalement, mais chaque gamète reçoit une chromatide de moins"},{"id":"b","texte":"Les chromosomes homologues se séparent normalement, mais chaque gamète reçoit un chromosome de plus"},{"id":"c","texte":"Les quatre gamètes reçoivent les deux chromosomes homologues, donc tous sont anormaux"},{"id":"d","texte":"La paire entière de chromosomes homologues part dans deux gamètes sur quatre, les deux autres n’en ont aucun"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0","r1c0"]},"explication":"Les gamètes 1 et 2 portent **deux exemplaires** du 21 : avec un gamète normal, le zygote en a trois."},{"cle":{"type":"nombre","valeur":47,"tolerance":0},"affichage":"47 chromosomes","explication":"24 + 23 = **47 chromosomes** : c’est la trisomie 21."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 gamètes","explication":"Les gamètes 3 et 4 sont normaux : **2 gamètes** sur 4."},{"cle":{"type":"choix","ids":["d"]},"explication":"La paire reste groupée et va **entière** dans une cellule fille : deux gamètes en ont deux exemplaires, deux n’en ont aucun."}]$ex$::jsonb),
  ('1f1a4c9e-2100-5971-9a90-3a8534d95b27'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre observations de terrain","competence":"analyser-document","situation":"Une naturaliste note quatre observations dans son carnet. Elle se demande, pour chacune, si le génome des êtres vivants concernés change ou non.","documents":[{"id":"carnet","type":"texte","genre":"article","titre":"Le carnet de la naturaliste","auteur":"Texte écrit pour l’exercice","blocs":["1. Sur les racines d’un trèfle, des nodosités abritent des bactéries Rhizobium qui fixent le diazote de l’air.","2. Dans un hôpital, des bactéries résistantes à un antibiotique transmettent leur gène de résistance à d’autres bactéries par contact.","3. Dans une forêt, un champignon s’associe aux racines d’un hêtre : c’est une mycorhize.","4. Dans un groupe de chimpanzés, les jeunes apprennent à pêcher les termites en regardant leur mère."]}],"questions":[{"enonce":"Touche le nom de la bactérie qui fixe le diazote de l’air.","aide":"Cherche le mot en italique dans la première observation.","type":"zone","document":"carnet","multiple":false},{"enonce":"Classe chaque situation selon que le génome des êtres vivants concernés change ou non.","aide":"Une symbiose et une tradition ne modifient pas l’ADN.","type":"categories","categories":[{"id":"c0","texte":"Le génome change"},{"id":"c1","texte":"Le génome ne change pas"}],"items":[{"id":"i0","texte":"Un gène d’origine virale, la syncytine, s’insère dans les génomes de mammifères"},{"id":"i1","texte":"Un trèfle abrite des bactéries Rhizobium dans ses racines"},{"id":"i2","texte":"Un champignon s’associe aux racines d’un hêtre"},{"id":"i3","texte":"Des chimpanzés apprennent à pêcher les termites"},{"id":"i4","texte":"Des bactéries échangent un gène de résistance à un antibiotique"},{"id":"i5","texte":"Un hybride stérile double son stock chromosomique et devient le blé tendre"}]},{"enonce":"Laquelle de ces observations illustre un transfert horizontal de gènes ?","aide":"Un gène passe d’un organisme à un autre sans reproduction.","type":"choix","options":[{"id":"a","texte":"L’observation 2, dans l’hôpital"},{"id":"b","texte":"L’observation 3, dans la forêt"},{"id":"c","texte":"L’observation 4, chez les chimpanzés"},{"id":"d","texte":"L’observation 1, sur les racines du trèfle"}],"multiple":false}]}$ex$::jsonb,
