  ('1f1a4c9e-2100-5971-9a90-3a8534d95b27'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Du graminée sauvage au blé tendre","competence":"raisonner","situation":"Le blé tendre est le produit de deux hybridations suivies de doublements du stock chromosomique. Chaque gamète des graminées sauvages A, B et D porte 7 chromosomes.","documents":[{"id":"ble","type":"chaine","disposition":"colonne","noeuds":[{"id":"z1","texte":"Deux graminées sauvages A et B (2n = 14 chacune)"},{"id":"z2","texte":"Hybride AB, stérile"},{"id":"z3","texte":"Doublement : amidonnier AABB (2n = 28)"},{"id":"z4","texte":"Croisé avec D (2n = 14) : hybride ABD, stérile"},{"id":"z5","texte":"Doublement : blé tendre AABBDD"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Combien de chromosomes l’hybride AB compte-t-il ?","aide":"Il reçoit un gamète de A et un gamète de B, de 7 chromosomes chacun.","type":"nombre","unite":"chromosomes"},{"enonce":"Combien de chromosomes l’hybride ABD compte-t-il ?","aide":"Un gamète de l’amidonnier (2n = 28) porte 14 chromosomes, un gamète de D en porte 7.","type":"nombre","unite":"chromosomes"},{"enonce":"Combien de chromosomes le blé tendre compte-t-il après doublement ?","aide":"Double le nombre de chromosomes de l’hybride ABD.","type":"nombre","unite":"chromosomes"},{"enonce":"Pourquoi le doublement du stock chromosomique restaure-t-il la fertilité ?","aide":"Dans l’hybride AB, les chromosomes de A et de B n’ont pas de partenaire homologue.","type":"choix","options":[{"id":"a","texte":"Le doublement supprime tous les chromosomes qui ne se ressemblent pas dans l’hybride"},{"id":"b","texte":"Le doublement fait disparaître la méiose, remplacée par une division de type mitose"},{"id":"c","texte":"Chaque chromosome retrouve un partenaire homologue pour s’apparier à la méiose"},{"id":"d","texte":"Les chromosomes en trop sont éliminés, ce qui rend le nombre de chromosomes impair"}],"multiple":false}]}$ex$::jsonb,
