  ('1f1a4c9e-2100-5971-9a90-3a8534d95b27'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une résistance qui voyage","competence":"argumenter","situation":"Des chercheurs étudient la diffusion d’une résistance à un antibiotique. Au laboratoire, ils cultivent une souche sensible (S) avec une souche résistante (R). À l’hôpital, ils suivent la part de bactéries résistantes.","documents":[{"id":"labo","type":"tableau","titre":"Expérience au laboratoire","colonnes":["Conditions de culture","Bactéries S devenues résistantes (pour 1 000)"],"lignes":[["Souche S seule",0],["Souches S et R mélangées, au contact",40],["Souches S et R séparées par un filtre fin",0]],"enteteLignes":true,"source":"Données imaginées pour l’exercice"},{"id":"hopital","type":"graphique","forme":"courbe","titre":"Bactéries résistantes dans un service","categories":["Année 0","Année 1","Année 2","Année 3","Année 4"],"series":[{"nom":"Bactéries résistantes","valeurs":[2,5,12,30,55],"teinte":"corail"}],"axeY":{"titre":"Bactéries résistantes","unite":"en % des bactéries isolées","min":0,"max":60,"pas":10},"axeX":{"titre":"Temps"},"valeurs":false,"source":"Données imaginées pour l’exercice"}],"questions":[{"enonce":"Touche la condition dans laquelle des bactéries S deviennent résistantes.","aide":"Cherche la ligne où le résultat n’est pas nul.","type":"zone","document":"labo","multiple":false},{"enonce":"Quel pourcentage des bactéries S est devenu résistant au contact de la souche R ?","aide":"40 pour 1 000 : divise par 1 000 puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Que conclure de la condition avec filtre ?","aide":"Le filtre empêche les bactéries de se toucher mais laisse passer le milieu.","type":"choix","options":[{"id":"a","texte":"Les bactéries S deviennent résistantes uniquement par reproduction sexuée"},{"id":"b","texte":"Le transfert du gène exige un contact entre les bactéries"},{"id":"c","texte":"La résistance apparaît dans la souche S quelle que soit la condition de culture"},{"id":"d","texte":"Le gène de résistance passe à travers n’importe quel filtre, même fin"}],"multiple":false},{"enonce":"Quel pourcentage de bactéries résistantes lit-on à l’année 3 ?","aide":"Lis la valeur de la courbe à l’année 3.","type":"nombre","unite":"%"},{"enonce":"Quels phénomènes expliquent cette hausse rapide dans le service ?","aide":"Le gène se transmet sans reproduction, et l’antibiotique trie les bactéries.","type":"choix","options":[{"id":"a","texte":"Une reproduction sexuée fréquente entre bactéries sensibles et bactéries résistantes du service"},{"id":"b","texte":"Le transfert horizontal du gène entre bactéries et la sélection des résistantes par l’antibiotique"},{"id":"c","texte":"Un changement de la forme des bactéries qui les rend plus faciles à détecter par les analyses"},{"id":"d","texte":"Une mutation que l’antibiotique provoque dans chaque bactérie qu’il rencontre dans le service"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0"]},"explication":"Seules les souches **mélangées, au contact**, donnent des bactéries S devenues résistantes."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 %","explication":"40 ÷ 1 000 = 0,04, soit **4 %**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le filtre supprime le contact : le transfert ne se fait plus. Le gène passe d’une bactérie à l’autre **sans reproduction**, par **contact**."},{"cle":{"type":"nombre","valeur":30,"tolerance":3},"affichage":"30 %","explication":"À l’année 3, environ **30 %** des bactéries sont résistantes."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le gène **se diffuse** par transfert horizontal, et l’antibiotique **sélectionne** les bactéries qui le portent : leur part augmente vite."}]$ex$::jsonb),
  ('2cc1db92-945c-570b-aad3-fd28ab3137f0'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La phalène et les cheminées","competence":"lire-graphique","situation":"Dans une région industrielle d’Angleterre, des chercheurs ont suivi la part des phalènes de forme sombre dans la population. Les troncs des bouleaux ont noirci avec la suie des usines, puis des lois contre la pollution ont été adoptées.","documents":[{"id":"phalene","type":"graphique","forme":"courbe","titre":"Phalènes de forme sombre","categories":["1850","1900","1950","1980","2000"],"series":[{"nom":"Forme sombre","valeurs":[2,95,98,40,10],"teinte":"gris"}],"axeY":{"titre":"Phalènes sombres","unite":"en % de la population","min":0,"max":100,"pas":20},"axeX":{"titre":"Année"},"valeurs":false,"source":"Tendances arrondies, pour l’exercice"}],"questions":[{"enonce":"Touche la date où la forme sombre est la plus fréquente.","aide":"Cherche le point le plus haut de la courbe.","type":"zone","document":"phalene","multiple":false},{"enonce":"Quel pourcentage de formes sombres lit-on en 1980 ?","aide":"Lis la valeur de la courbe à 1980.","type":"nombre","unite":"%"},{"enonce":"Pourquoi la forme sombre augmente-t-elle entre 1850 et 1900 ?","aide":"Pense à qui mange les phalènes, et à ce qu’il voit sur un tronc noir.","type":"choix","options":[{"id":"a","texte":"Les phalènes sombres se reproduisent deux fois plus souvent que les claires, sans raison liée au milieu"},{"id":"b","texte":"La suie des usines provoque chez les phalènes la mutation qui leur donne une couleur sombre"},{"id":"c","texte":"Sur les troncs noircis, elle est moins repérée par les oiseaux, donc plus de phalènes sombres survivent"},{"id":"d","texte":"Les phalènes claires quittent la région et sont remplacées par des phalènes sombres venues d’ailleurs"}],"multiple":false},{"enonce":"Pourquoi la forme sombre régresse-t-elle après 1950 ?","aide":"Le milieu a changé : comment sont les troncs maintenant ?","type":"choix","options":[{"id":"a","texte":"Les troncs s’éclaircissent avec la baisse de la pollution : la forme claire est de nouveau mieux camouflée"},{"id":"b","texte":"La forme sombre mute en forme claire à chaque génération quand l’air devient plus propre autour des bouleaux"},{"id":"c","texte":"Les lois interdisent de capturer les phalènes sombres, ce qui fait disparaître le risque lié à la prédation"},{"id":"d","texte":"Les oiseaux perdent la vue des couleurs, si bien que la forme sombre n’est plus un avantage pour les phalènes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"En **1950**, la forme sombre atteint environ 98 % de la population."},{"cle":{"type":"nombre","valeur":40,"tolerance":4},"affichage":"40 %","explication":"En 1980, la forme sombre représente environ **40 %** de la population."},{"cle":{"type":"choix","ids":["c"]},"explication":"Sur un tronc noir, la forme sombre est **mieux camouflée** : elle survit et se reproduit davantage. C’est la **sélection naturelle**."},{"cle":{"type":"choix","ids":["a"]},"explication":"La sélection est relative à un **milieu qui change** : quand les troncs s’éclaircissent, l’avantage s’inverse."}]$ex$::jsonb),
  ('2cc1db92-945c-570b-aad3-fd28ab3137f0'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Une population conforme ?","competence":"modeliser","situation":"On étudie un gène à deux allèles A et a dans deux populations de 500 individus. Le modèle de Hardy-Weinberg sert de référence : il prévoit des fréquences de génotypes p², 2pq et q².","documents":[{"id":"pop1","type":"tableau","titre":"Population 1","colonnes":["Génotype","Effectif observé"],"lignes":[["AA",245],["Aa",210],["aa",45]],"enteteLignes":true,"source":"500 individus"},{"id":"pop2","type":"tableau","titre":"Population 2","colonnes":["Génotype","Effectif observé"],"lignes":[["AA",300],["Aa",100],["aa",100]],"enteteLignes":true,"source":"500 individus"}],"questions":[{"enonce":"Quelle est la fréquence de l’allèle A dans la population 1 ?","aide":"Il y a 1 000 allèles. Compte ceux de A : 2 par AA, 1 par Aa.","type":"nombre"},{"enonce":"La population 1 est-elle conforme au modèle de Hardy-Weinberg ?","aide":"Calcule p² × 500, 2pq × 500 et q² × 500 avec p = 0,7 et q = 0,3.","type":"choix","options":[{"id":"a","texte":"Non : il y a beaucoup plus d’individus aa que le modèle ne le prévoit"},{"id":"b","texte":"On ne peut pas savoir : le modèle ne permet aucune comparaison avec des effectifs observés"},{"id":"c","texte":"Oui : les effectifs observés (245, 210, 45) sont égaux aux effectifs attendus avec p = 0,7"},{"id":"d","texte":"Non : il y a beaucoup moins d’hétérozygotes que le modèle ne le prévoit"}],"multiple":false},{"enonce":"Dans la population 2, p vaut aussi 0,7. Combien d’hétérozygotes Aa le modèle prévoit-il ?","aide":"Calcule 2pq × 500.","type":"nombre","unite":"individus"},{"enonce":"Touche l’effectif observé d’hétérozygotes dans la population 2.","aide":"Cherche la ligne du génotype Aa.","type":"zone","document":"pop2","multiple":false},{"enonce":"Que conclure pour la population 2 ?","aide":"Compare l’effectif observé d’hétérozygotes à l’effectif attendu.","type":"choix","options":[{"id":"a","texte":"La population 2 est conforme, car la fréquence de l’allèle A y vaut aussi 0,7 comme dans la population 1"},{"id":"b","texte":"Le modèle de Hardy-Weinberg est faux, puisqu’il ne décrit pas du tout la population 2"},{"id":"c","texte":"Au moins une hypothèse du modèle n’est pas respectée : une force évolutive ou des croisements non aléatoires"},{"id":"d","texte":"La population 2 est conforme, car le nombre total d’individus y est aussi de 500 comme dans la population 1"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.7,"tolerance":0},"affichage":"0,7","explication":"(2 × 245 + 210) ÷ 1 000 = 700 ÷ 1 000 = **0,7**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Attendus : 0,49 × 500 = 245 ; 0,42 × 500 = 210 ; 0,09 × 500 = 45. **Ils sont identiques** aux effectifs observés."},{"cle":{"type":"nombre","valeur":210,"tolerance":0},"affichage":"210 individus","explication":"2 × 0,7 × 0,3 × 500 = 0,42 × 500 = **210 individus**."},{"cle":{"type":"zone","ids":["r1c1"]},"explication":"On observe seulement **100** hétérozygotes, contre 210 attendus."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un **déficit d’hétérozygotes** signale que le modèle n’est pas respecté : c’est l’intérêt de cette **référence nulle**."}]$ex$::jsonb),
  ('2cc1db92-945c-570b-aad3-fd28ab3137f0'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le hasard ou le tri ?","competence":"raisonner","situation":"Trois populations isolées, sans migration ni mutation, sont suivies pendant 20 générations. On mesure la fréquence d’un même allèle au départ fixée à 50 %.","documents":[{"id":"allele","type":"graphique","forme":"courbe","titre":"Fréquence de l’allèle étudié","categories":["0","5","10","15","20"],"series":[{"nom":"Population A (20 individus)","valeurs":[50,65,40,75,100],"teinte":"corail"},{"nom":"Population B (2 000 individus)","valeurs":[50,51,49,50,51],"teinte":"bleu"},{"nom":"Population C (2 000 individus)","valeurs":[50,58,68,79,88],"teinte":"vert"}],"axeY":{"titre":"Fréquence de l’allèle","unite":"en %","min":0,"max":100,"pas":20},"axeX":{"titre":"Générations"},"valeurs":false,"source":"Simulation simplifiée"},{"id":"regle","type":"texte","genre":"article","titre":"Ce que l’on sait des populations","auteur":"Texte écrit pour l’exercice","blocs":["Dans les populations A et B, l’allèle n’apporte aucun avantage : les individus qui le portent se reproduisent autant que les autres.","Dans la population C, l’allèle augmente de 10 % les chances de se reproduire."]}],"questions":[{"enonce":"Quel écart de fréquence sépare les populations A et B à la génération 20 ?","aide":"Lis 100 pour A et environ 51 pour B.","type":"nombre","unite":"points"},{"enonce":"Quelle population illustre la sélection naturelle ?","aide":"Cherche la population où l’allèle avantageux gagne du terrain de façon régulière.","type":"choix","options":[{"id":"a","texte":"La population A, où la fréquence fluctue au hasard avant d’atteindre 100 %"},{"id":"b","texte":"La population B, où la fréquence reste proche de 50 % pendant toute la durée"},{"id":"c","texte":"La population C, où un allèle avantageux se répand de façon régulière"},{"id":"d","texte":"Aucune des trois, car la sélection n’agit jamais sur la fréquence d’un allèle"}],"multiple":false},{"enonce":"Pourquoi A varie-t-elle au hasard alors que B reste stable ?","aide":"Compare les effectifs : 20 contre 2 000 individus.","type":"choix","options":[{"id":"a","texte":"La sélection naturelle est plus forte dans B que dans A, et stabilise la fréquence de l’allèle"},{"id":"b","texte":"La dérive génétique est forte dans une population de petit effectif et faible dans une grande"},{"id":"c","texte":"Les mutations sont plus fréquentes dans une petite population que dans une grande"},{"id":"d","texte":"Les individus de A se reproduisent moins bien que ceux de B, ce qui fait fluctuer l’allèle"}],"multiple":false},{"enonce":"Dans A, l’allèle atteint 100 %. Que peut-on en conclure ?","aide":"Relis le texte sur les populations A et B.","type":"choix","options":[{"id":"a","texte":"Que l’allèle a été transféré depuis la population B par migration d’individus entre les deux"},{"id":"b","texte":"Rien sur un avantage : il n’en apporte aucun et le hasard a suffi à le fixer"},{"id":"c","texte":"Que la population A a subi une forte sélection naturelle en faveur de cet allèle"},{"id":"d","texte":"Qu’il est avantageux, puisque sa fréquence a atteint 100 % dans cette population"}],"multiple":false}]}$ex$::jsonb,
