   $ex${"titre":"Dans le sarcomère","competence":"observer-schema","situation":"Au microscope électronique, le muscle strié montre une alternance régulière de filaments. Le schéma représente un sarcomère et le tableau compare sa longueur et celle de ses filaments au repos et contracté.","documents":[{"id":"sarco","type":"schema","titre":"Un sarcomère (schéma simplifié)","largeur":340,"hauteur":215,"elements":[{"forme":"rect","x":37,"y":28,"l":6,"h":122,"teinte":"encre","motif":"plein","id":"z1","zone":true},{"forme":"rect","x":297,"y":28,"l":6,"h":122,"teinte":"encre","motif":"plein","id":"z2","zone":true},{"forme":"rect","x":43,"y":44,"l":117,"h":6,"teinte":"encre","motif":"plein","id":"z3","zone":true},{"forme":"rect","x":43,"y":79,"l":117,"h":6,"teinte":"encre","motif":"plein","id":"z4","zone":true},{"forme":"rect","x":43,"y":114,"l":117,"h":6,"teinte":"encre","motif":"plein","id":"z5","zone":true},{"forme":"rect","x":180,"y":44,"l":117,"h":6,"teinte":"encre","motif":"plein","id":"z6","zone":true},{"forme":"rect","x":180,"y":79,"l":117,"h":6,"teinte":"encre","motif":"plein","id":"z7","zone":true},{"forme":"rect","x":180,"y":114,"l":117,"h":6,"teinte":"encre","motif":"plein","id":"z8","zone":true},{"forme":"rect","x":100,"y":60,"l":140,"h":10,"teinte":"encre","motif":"plein","id":"z9","zone":true},{"forme":"rect","x":100,"y":95,"l":140,"h":10,"teinte":"encre","motif":"plein","id":"z10","zone":true},{"forme":"ligne","de":[40,172],"a":[300,172],"fleche":"deux"},{"forme":"texte","x":170,"y":196,"texte":"Un sarcomère","taille":"petit","ancre":"milieu","italique":true}]},{"id":"long","type":"tableau","titre":"Longueurs mesurées","colonnes":["État","Sarcomère (µm)","Actine (µm)","Myosine (µm)"],"lignes":[["Relâché","2,4","1,0","1,6"],["Contracté","1,8","1,0","1,6"]],"enteteLignes":true,"source":"Valeurs simplifiées"}],"questions":[{"enonce":"Touche les deux filaments épais de myosine.","aide":"Ce sont les deux filaments les plus gros, au centre du sarcomère.","type":"zone","document":"sarco","multiple":true},{"enonce":"Touche la strie Z située à gauche.","aide":"Les stries Z sont les deux limites verticales du sarcomère.","type":"zone","document":"sarco","multiple":false},{"enonce":"De quel pourcentage le sarcomère se raccourcit-il entre l’état relâché et l’état contracté ?","aide":"Calcule la différence de longueur, puis divise par la longueur au repos.","type":"nombre","unite":"%"},{"enonce":"Que montre le tableau sur les filaments ?","aide":"Compare les colonnes Actine et Myosine entre les deux lignes.","type":"choix","options":[{"id":"a","texte":"Leur longueur double pendant la contraction, ce qui écarte les deux stries Z"},{"id":"b","texte":"Leur longueur ne change pas : ils glissent les uns sur les autres"},{"id":"c","texte":"Les filaments de myosine se raccourcissent, ce qui rapproche les deux stries Z"},{"id":"d","texte":"Les filaments d’actine se raccourcissent, ce qui rapproche les deux stries Z"}],"multiple":false}]}$ex$::jsonb,
