  ('79ed36ff-e0fc-5c96-aae2-2a70eac8b974'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le muscle après la mort","competence":"experimenter","situation":"Des fibres musculaires à la membrane perméabilisée sont placées dans trois solutions. Après la mort d’un animal, le calcium s’échappe du réticulum sarcoplasmique et la régénération de l’ATP s’arrête.","documents":[{"id":"solutions","type":"tableau","titre":"Trois solutions, trois résultats","colonnes":["Condition","Ca²⁺","ATP","Observation"],"lignes":[["1","présent","présent","la fibre se raccourcit"],["2","absent","présent","la fibre reste relâchée"],["3","présent","absent","la fibre reste raide, non raccourcie"]],"enteteLignes":true,"source":"Résultats simplifiés"}],"questions":[{"enonce":"Touche la condition qui correspond à un muscle après la mort.","aide":"Après la mort, il y a du calcium mais plus d’ATP.","type":"zone","document":"solutions","multiple":false},{"enonce":"Pourquoi la fibre reste-t-elle raide dans la condition 3 ?","aide":"Que fait la fixation d’une molécule d’ATP sur une tête de myosine ?","type":"choix","options":[{"id":"a","texte":"Sans ATP, les filaments d’actine se raccourcissent puis restent figés à cette longueur"},{"id":"b","texte":"Sans ATP, les têtes de myosine restent accrochées à l’actine et ne peuvent pas se détacher"},{"id":"c","texte":"Sans ATP, les stries Z se soudent entre elles et empêchent tout glissement des filaments"},{"id":"d","texte":"Sans ATP, le calcium quitte la fibre et bloque définitivement les filaments de myosine"}],"multiple":false},{"enonce":"Pourquoi la fibre ne se contracte-t-elle pas dans la condition 2 ?","aide":"Le calcium intervient avant que les têtes de myosine ne se fixent.","type":"choix","options":[{"id":"a","texte":"Sans Ca²⁺, les sites de fixation de la myosine restent masqués sur l’actine"},{"id":"b","texte":"Sans Ca²⁺, l’ATP ne peut plus être hydrolysé et reste inutilisable dans la fibre"},{"id":"c","texte":"Sans Ca²⁺, la myosine ne peut plus être fabriquée par la fibre musculaire"},{"id":"d","texte":"Sans Ca²⁺, les filaments d’actine s’allongent et ne peuvent plus glisser"}],"multiple":false},{"enonce":"Que montre l’ensemble du tableau ?","aide":"Regarde ce qui manque dans les conditions où la fibre ne se raccourcit pas.","type":"choix","options":[{"id":"a","texte":"La contraction exige à la fois du Ca²⁺ et de l’ATP"},{"id":"b","texte":"La contraction exige seulement de l’ATP, le Ca²⁺ étant inutile à la contraction"},{"id":"c","texte":"La contraction exige seulement du Ca²⁺, l’ATP étant inutile à la contraction"},{"id":"d","texte":"La contraction ne dépend d’aucune de ces deux molécules dans la fibre musculaire"}],"multiple":false}]}$ex$::jsonb,
