  ('79ed36ff-e0fc-5c96-aae2-2a70eac8b974'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Finesse ou puissance ?","competence":"raisonner","situation":"Un motoneurone commande toutes les fibres de son unité motrice. Le tableau compare deux muscles ; la courbe montre la force d’un muscle selon la part d’unités motrices recrutées.","documents":[{"id":"um","type":"tableau","titre":"Deux muscles","colonnes":["Muscle","Fibres","Motoneurones"],"lignes":[["Muscle de l’œil",1200,400],["Muscle du mollet",1000000,600]],"enteteLignes":true,"source":"Valeurs simplifiées, pour l’exercice"},{"id":"force","type":"graphique","forme":"courbe","titre":"Force et recrutement","categories":["0","25","50","75","100"],"series":[{"nom":"Force du muscle","valeurs":[0,40,100,180,300],"teinte":"violet"}],"axeY":{"titre":"Force","unite":"en newtons","min":0,"max":300,"pas":50},"axeX":{"titre":"Unités motrices recrutées (%)"},"valeurs":true,"source":"Valeurs simplifiées"}],"questions":[{"enonce":"Combien de fibres une unité motrice compte-t-elle en moyenne dans le muscle de l’œil ?","aide":"Divise le nombre de fibres par le nombre de motoneurones.","type":"nombre","unite":"fibres"},{"enonce":"Même question pour le muscle du mollet, arrondie à l’unité.","aide":"Divise 1 000 000 par 600.","type":"nombre","unite":"fibres"},{"enonce":"Pourquoi le muscle de l’œil règle-t-il sa force plus finement que celui du mollet ?","aide":"Compare le nombre de fibres par unité motrice dans les deux muscles.","type":"choix","options":[{"id":"a","texte":"Chaque unité motrice recrutée n’y ajoute que quelques fibres, donc une très petite force"},{"id":"b","texte":"Chaque unité motrice recrutée y ajoute des milliers de fibres, donc une très grande force"},{"id":"c","texte":"Le muscle de l’œil n’est commandé par aucun motoneurone, contrairement au muscle du mollet"},{"id":"d","texte":"Le muscle de l’œil a beaucoup plus de fibres que le muscle du mollet dans chaque unité"}],"multiple":false},{"enonce":"Touche la part d’unités motrices recrutées pour laquelle la force vaut 180 N.","aide":"Cherche la valeur 180 sur la courbe.","type":"zone","document":"force","multiple":false},{"enonce":"De combien la force augmente-t-elle quand on passe de 50 % à 75 % d’unités motrices recrutées ?","aide":"Retire 100 à 180.","type":"nombre","unite":"N"}]}$ex$::jsonb,
