  ('316c7240-8d0d-5e24-bfb8-0dc25fb1e8ee'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Qui fournit l’ATP, et quand ?","competence":"lire-graphique","situation":"Pendant un effort très intense, la fibre musculaire régénère son ATP par trois voies qui fonctionnent en même temps. La courbe donne la part de chacune selon la durée de l’effort.","documents":[{"id":"voies","type":"graphique","forme":"courbe","titre":"Part de l’ATP fournie par chaque voie","categories":["5","10","30","60","120"],"series":[{"nom":"Phosphocréatine","valeurs":[80,50,15,5,2],"teinte":"ambre"},{"nom":"Fermentation lactique","valeurs":[15,40,50,35,18],"teinte":"corail"},{"nom":"Respiration cellulaire","valeurs":[5,10,35,60,80],"teinte":"bleu"}],"axeY":{"titre":"Part de l’ATP","unite":"en %","min":0,"max":100,"pas":20},"axeX":{"titre":"Durée de l’effort (secondes)"},"valeurs":false,"source":"Données simplifiées"}],"questions":[{"enonce":"Touche le moment où la respiration cellulaire devient la voie qui fournit le plus d’ATP.","aide":"Cherche la première durée où la courbe de la respiration est au-dessus des deux autres.","type":"zone","document":"voies","multiple":false},{"enonce":"Quelle part de l’ATP la fermentation lactique fournit-elle à 30 secondes ?","aide":"Lis la valeur de la courbe de la fermentation à la graduation 30.","type":"nombre","unite":"%"},{"enonce":"Que montre l’évolution de la phosphocréatine ?","aide":"Regarde la valeur de cette courbe à 5 s puis à 60 s.","type":"choix","options":[{"id":"a","texte":"Sa contribution est nulle au début de l’effort et n’apparaît qu’après une minute"},{"id":"b","texte":"Sa contribution reste stable pendant deux minutes, car sa réserve est très importante"},{"id":"c","texte":"Sa contribution s’effondre en quelques secondes car sa réserve est très vite épuisée"},{"id":"d","texte":"Sa contribution augmente tout au long de l’effort, car sa réserve se renouvelle vite"}],"multiple":false},{"enonce":"Que montre la valeur des trois courbes à 10 secondes ?","aide":"Regarde si une seule courbe vaut 100 % à 10 s.","type":"choix","options":[{"id":"a","texte":"Une seule voie fonctionne à la fois, les deux autres attendent leur tour"},{"id":"b","texte":"La phosphocréatine fournit la totalité de l’ATP pendant les dix premières secondes"},{"id":"c","texte":"Les trois voies fonctionnent en même temps, seule leur part relative change"},{"id":"d","texte":"La respiration cellulaire est la seule voie qui soit active pendant les premières secondes"}],"multiple":false}]}$ex$::jsonb,
